pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {XBORNID} from "../src/XBORNID.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    XBORNID c;

    function setUp() public {
        c = new XBORNID();
    }

    function _run(address ownerCandidate) internal {
        ownerCandidate = address(this);
        try c.XBornID() {} catch { return; }
        uint256 bal;
        try c.balanceOf(address(this)) returns (uint256 __r) { bal = __r; } catch { return; }
        uint256 dist;
        try c.totalDistributed() returns (uint256 __r) { dist = __r; } catch { return; }
        assertTrue(bal == dist);
    }

    function testFuzz_run(address ownerCandidate) public {
        _run(ownerCandidate);
    }

    receive() external payable {}
}
